{"file_path": "/Users/squirrel/Desktop/harness/bench/results/delve-v2/05-dungeon/dsh-1/workspace/test/undo.test.js", "content": "import test from 'node:test';
import assert from 'node:assert/strict';

import {
  createGame,
  loadGame,
  applyKey,
  runScript,
  MAX_UNDO,
} from '../src/game.js';

const ROOM = [
  '#########',
  '#.......#',
  '#.......#',
  '#.......#',
  '#.......#',
  '#.......#',
  '#########',
];

const CENTRE = { x: 4, y: 3 };

function fixture(extra) {
  return createGame({ seed: 1, map: ROOM, player: { ...CENTRE }, ...extra });
}

// A tiny fixture with a stair the player is already standing on.
function stairFixture(extra) {
  return createGame({
    seed: 1,
    depth: 1,
    map: ['#####', '#.>.#', '#####'],
    player: { x: 2, y: 1 },
    ...extra,
  });
}

test('a new game starts with an empty, coherent history', () => {
  const game = createGame({ seed: 5 });
  assert.deepEqual(game.state.history, []);
  assert.equal(game.state.undo, 0);
  assert.equal(game.undo(), false);
  assert.equal(game.state.undo, 0);
});

test('undo reverts a move exactly, including turn, hash and rng', () => {
  const game = createGame({ seed: 12 });
  const beforeHash = game.hash();
  const beforeState = structuredClone(game.state);

  const messages = game.act({ type: 'move', dx: 1, dy: 0 });
  assert.deepEqual(messages, []);
  assert.equal(game.state.turn, 1);
  assert.equal(game.state.undo, 1);

  assert.equal(game.undo(), true);
  assert.equal(game.state.turn, 0);
  assert.equal(game.state.undo, 0);
  assert.equal(game.hash(), beforeHash);
  // history is the only field allowed to differ (it is now consumed)
  assert.deepEqual(
    { ...game.state, history: beforeState.history },
    beforeState,
  );
});

test('a wall bump, an empty pickup and invalid use/drop leave nothing to undo', () => {
  const game = createGame({
    seed: 1,
    map: ['###', '#.#', '###'],
    player: { x: 1, y: 1 },
  });
  assert.deepEqual(game.act({ type: 'move', dx: -1, dy: 0 }), ['There is a wall in the way.']);
  assert.deepEqual(game.act({ type: 'pickup' }), ['There is nothing here.']);
  assert.deepEqual(game.act({ type: 'use', index: 0 }), ['You have no such item.']);
  assert.deepEqual(game.act({ type: 'drop', index: 0 }), ['You have no such item.']);
  assert.deepEqual(game.act({ type: 'descend' }), ['There are no stairs here.']);
  assert.equal(game.state.turn, 0);
  assert.equal(game.state.undo, 0);
  assert.equal(game.undo(), false);
});

test('undo restores the log, the player HP, and replays identically', () => {
  const game = fixture({
    monsters: [{ type: 'rat', x: CENTRE.x + 1, y: CENTRE.y }],
  });
  const beforeHash = game.hash();
  const beforeHp = game.state.player.hp;

  const first = game.act({ type: 'wait' });
  assert.deepEqual(first, ['The rat hits you for 1.']);
  assert.equal(game.state.player.hp, beforeHp - 1);
  assert.deepEqual(game.state.log, ['The rat hits you for 1.']);

  assert.equal(game.undo(), true);
  assert.deepEqual(game.state.log, []);
  assert.equal(game.state.player.hp, beforeHp);
  assert.equal(game.hash(), beforeHash);

  const again = game.act({ type: 'wait' });
  assert.deepEqual(again, first);
  assert.equal(game.state.player.hp, beforeHp - 1);
});

test('undo brings killed monsters and granted xp back', () => {
  const game = fixture({
    monsters: [{ type: 'rat', x: CENTRE.x + 1, y: CENTRE.y }],
  });
  game.act({ type: 'move', dx: 1, dy: 0 });
  assert.equal(game.state.monsters.length, 0);
  assert.equal(game.state.player.xp, 3);
  assert.equal(game.state.player.x, CENTRE.x + 1);

  assert.equal(game.undo(), true);
  assert.equal(game.state.monsters.length, 1);
  assert.deepEqual(game.state.monsters[0], {
    id: 1,
    type: 'rat',
    x: CENTRE.x + 1,
    y: CENTRE.y,
    hp: 4,
    maxHp: 4,
    attack: 2,
    defense: 0,
    xp: 3,
  });
  assert.equal(game.state.player.xp, 0);
  assert.equal(game.state.player.x, CENTRE.x);
});

test('undo right after descending brings the previous level back', () => {
  const game = stairFixture();
  const beforeHash = game.hash();

  game.act({ type: 'descend' });
  assert.equal(game.state.depth, 2);
  assert.equal(game.state.turn, 1);
  assert.notEqual(game.state.tiles.join(''), ['#####', '#.>.#', '#####'].join(''));

  assert.equal(game.undo(), true);
  assert.equal(game.state.depth, 1);
  assert.equal(game.state.turn, 0);
  assert.deepEqual(game.state.tiles, ['#####', '#.>.#', '#####']);
  assert.equal(game.state.player.x, 2);
  assert.equal(game.state.player.y, 1);
  assert.equal(game.hash(), beforeHash);
});

test('a repeated descend after undo generates the same level and rng', () => {
  const game = stairFixture();
  game.act({ type: 'descend' });
  const first = game.serialize();
  const firstHash = game.hash();

  game.undo();
  game.act({ type: 'descend' });
  assert.equal(game.hash(), firstHash);
  assert.equal(game.serialize(), first);
});

test('at most ten turns can be rewound and older history is discarded', () => {
  const game = fixture();
  for (let i = 0; i < MAX_UNDO + 2; i += 1) game.act({ type: 'wait' });
  assert.equal(game.state.turn, MAX_UNDO + 2);
  assert.equal(game.state.history.length, MAX_UNDO);
  assert.equal(game.state.undo, MAX_UNDO);

  for (let i = 0; i < MAX_UNDO; i += 1) assert.equal(game.undo(), true);
  assert.equal(game.state.turn, MAX_UNDO + 2 - MAX_UNDO);
  assert.equal(game.state.undo, 0);
  assert.equal(game.undo(), false);
});

test('undo replays the same RNG stream across a cap-sized history', () => {
  const game = fixture();
  runScript(game, '................................');
  const actions = [];
  for (let i = 0; i < MAX_UNDO; i += 1) {
    actions.push(game.hash());
    game.undo();
  }
  for (let i = 0; i < MAX_UNDO; i += 1) {
    game.act({ type: 'wait' });
    assert.equal(game.hash(), actions[i]);
  }
});

test('applyKey("z") rewinds, or reports that there is nothing to rewind', () => {
  const game = fixture();
  assert.deepEqual(applyKey(game, 'z'), ['Nothing to rewind.']);

  applyKey(game, 'l');
  assert.equal(game.state.turn, 1);
  assert.equal(game.state.player.x, CENTRE.x + 1);

  assert.deepEqual(applyKey(game, 'z'), ['You rewind time.']);
  assert.equal(game.state.turn, 0);
  assert.equal(game.state.player.x, CENTRE.x);
  assert.deepEqual(applyKey(game, 'z'), ['Nothing to rewind.']);
});

test('runScript accepts z like any other key', () => {
  const game = fixture();
  runScript(game, 'llz');
  assert.equal(game.state.player.x, CENTRE.x + 1);
  assert.equal(game.state.turn, 1);
  assert.equal(game.state.undo, 1);
});

test('undo works after the fatal blow and after winning', () => {
  const trolls = [];
  for (const [x, y] of [
    [1, 1],
    [2, 1],
    [3, 1],
    [1, 2],
    [3, 2],
  ]) {
    trolls.push({ type: 'troll', x, y });
  }
  const doomed = createGame({
    seed: 1,
    map: ['#####', '#...#', '#...#', '#...#', '#####'],
    player: { x: 2, y: 2 },
    monsters: trolls,
  });
  doomed.act({ type: 'wait' });
  assert.equal(doomed.state.status, 'dead');
  assert.equal(doomed.undo(), true);
  assert.equal(doomed.state.status, 'playing');
  assert.equal(doomed.state.player.hp, 30);
  assert.equal(doomed.state.turn, 0);

  const winner = fixture({ items: [{ kind: 'amulet', x: CENTRE.x, y: CENTRE.y }] });
  winner.act({ type: 'pickup' });
  assert.equal(winner.state.status, 'won');
  assert.equal(winner.undo(), true);
  assert.equal(winner.state.status, 'playing');
  assert.equal(winner.state.items.length, 1);
});

test('serialize/load preserves the rewind history', () => {
  const game = fixture();
  game.act({ type: 'wait' });
  game.act({ type: 'wait' });

  const json = game.serialize();
  const clone = loadGame(json);
  assert.equal(clone.state.undo, 2);
  assert.deepEqual(clone.state.history, game.state.history);
  assert.equal(clone.hash(), game.hash());

  assert.equal(clone.undo(), true);
  assert.equal(game.undo(), true);
  assert.deepEqual(clone.state, game.state);
  assert.equal(clone.serialize(), game.serialize());
});

test('hash ignores the history and undo fields', () => {
  const game = createGame({ seed: 21 });
  runScript(game, 'jjj');
  const base = game.hash();

  game.state.undo = 7;
  game.state.history = [];
  assert.equal(game.hash(), base);

  game.state.history = [{ anything: true }];
  game.state.undo = 1;
  assert.equal(game.hash(), base);
});
"}

